$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = 'Storitev Companion Chat trenutno ni na voljo. Prosite skrbnika spletnega mesta, naj preveri povezavo vtičnika AI.';
$t['The connection could not be renewed. Please reconnect your account.'] = 'Povezave ni bilo mogoče obnoviti. Znova povežite svoj račun.';
$t['The connection expired and could not be renewed. Please reconnect your account.'] = 'Povezava je potekla in je ni bilo mogoče obnoviti. Znova povežite svoj račun.';
$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'Povezava s ciljem se je med pretakanjem prekinila. To je lahko začasna težava z omrežjem; FFMPEG se bo poskusil znova povezati.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'Povezava z YouTube je bila prekinjena. Nalaganje je bilo zaustavljeno in ga je mogoče nadaljevati.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = 'Povezava je bila prekinjena. Pred ponovnim poskusom te naročnine preverite svoj račun.';
$t['The connection was renewed.'] = 'Povezava je bila obnovljena.';
$t['The connection window was closed before the authorization finished. No account was connected.'] = 'Okno za povezavo je bilo zaprto, preden se je avtorizacija končala. Noben račun ni bil povezan.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'Pretvorjene datoteke so bile ohranjene. Za ponovni poskus prenosa se obrnite na skrbnika spletnega mesta; videoposnetka vam ni treba znova naložiti.';
$t['The converted video could not be sent back to this site.'] = 'Pretvorjenega videoposnetka ni bilo mogoče poslati nazaj na to spletno mesto.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'Stranke izbrane kartice. Iščite, razvrščajte, kopirajte e-poštne naslove ali vse izvozite v preglednico.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'Dnevna kvota nalaganja na YouTube za to spletno mesto je dosežena. Nalaganje bo znova na voljo po polnoči po pacifiškem času. Poskusite znova pozneje.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'Različica podatkovne baze se spremeni le ob uveljavitvi migracije podatkovne baze. Ni nujno, da se ujema z oznako izdaje ali commitom.';
$t['The default'] = 'Privzeto';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'Ciljni strežnik RTMP je zavrnil povezavo. Preverite URL pretoka in se prepričajte, da je strežnik dosegljiv.';
$t['The destination server requires authentication. Check the stream key.'] = 'Ciljni strežnik zahteva overitev. Preverite ključ pretoka.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'Ciljni strežnik je vrnil napako 403. Ključ pretoka je morda neveljaven ali potekel.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'Ciljni videoposnetek je bil odstranjen ali ga ta račun ne more urejati. Preverite videoposnetek in dostop računa na spletnem mestu.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'The download is controlled by the system, there is nothing to check on the user';
$t['The download permission is site wide, so there is nothing to check on the video'] = 'Dovoljenje za prenos velja za celotno spletno mesto, zato na videoposnetku ni ničesar za preverjanje';
$t['The download permission is site wide, so there is nothing to check onthe video'] = 'The download permission is site wide, so there is nothing to check onthe video';
$t['The email is invalid'] = 'The email is invalid';
$t['The encoder could not download the original file.'] = 'Kodirnik ni mogel prenesti izvirne datoteke.';
$t['The encoder could not find this video on the site.'] = 'Kodirnik tega videoposnetka ni našel na spletnem mestu.';
$t['The encoder did not confirm that the video was added to the queue. Please retry.'] = 'Kodirnik ni potrdil, da je bil videoposnetek dodan v čakalno vrsto. Poskusite znova.';
$t['The encoder is running out of disk space'] = 'Kodirniku zmanjkuje prostora na disku';
$t['The encoder reported an unexpected error.'] = 'Kodirnik je sporočil nepričakovano napako.';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = 'Postopek kodiranja se je nepričakovano ustavil, samodejni ponovni poskusi pa so prav tako spodleteli.';
$t['The encoding queue is stalled'] = 'Čakalna vrsta kodiranja je obstala';
$t['The event purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'Nakupa dogodka ni bilo mogoče dokončati. Plačilo iz denarnice ni bilo odšteto. Pred ponovnim poskusom preverite stanje.';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = 'Datoteke ni bilo mogoče pretvoriti. Morda je poškodovana ali uporablja format, ki ga kodirnik ne podpira.';
$t['The file must be an .vtt file!'] = 'Datoteka mora imeti končnico vtt!';
$t['The file must be an .vtt or .srt file!'] = 'Datoteka mora biti v obliki .vtt ali .srt!';
$t['The final charge uses the duration measured during processing. A connected Marketplace wallet is required.'] = 'Končni znesek temelji na trajanju, izmerjenem med obdelavo. Potrebna je povezana denarnica Marketplace.';
$t['The following movie contains materials that are not suitable for children 17 and under.'] = 'Naslednji film vsebuje gradivo, ki ni primerno za otroke, stare 17 let ali manj.';
