$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = 'Zgornji podatki se ujemajo z našimi uradnimi evidencami in potrjujejo pristnost tega potrdila.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'Vhodni pretok vsebuje neveljavne podatke. Izvorni HLS morda še ni pripravljen ali je bil pretok prekinjen.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'Nameščeni paket PHP vsebuje oba popravka, vendar ta spletni proces še vedno izvaja kopijo, naloženo pred posodobitvijo. Znova zaženite Apache ali PHP-FPM.';
