$t['There is no Pay Per View plan yet. Create one in the Pay-Per-View plugin, PPV Plans tab.'] = 'Paketa Pay Per View še ni. Ustvarite ga v vtičniku Pay-Per-View, na zavihku PPV Plans.';
$t['There is no plan that can hold videos yet. Create one in the PPV Plans tab, then come back here.'] = 'Paketa, ki bi lahko vseboval videoposnetke, še ni. Ustvarite ga na zavihku PPV Plans in se nato vrnite sem.';
$t['There is no streaming now'] = 'Trenutno ni aktivno nobeno pretočno predvajanje';
