$t['The request to the social network failed. Please try again later.'] = 'Zahteva do družbenega omrežja ni uspela. Poskusite znova pozneje.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'Strežnik za ponovno oddajanje ne more doseči cilja. Preverite omrežno povezavo.';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'Isto opozorilo se ponovi največ vsakih %s, dokler težava traja.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'Isto opozorilo se ponovi največ vsakih nekaj ur, dokler težava traja.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'Izbrana kamera ali mikrofon ni na voljo. Izberite drugo napravo.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Izbrani položaj je označen na resnični strani. Mobilni predogled spremeni le položaje oglasov; preostali del strani uporablja napravo vašega brskalnika.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Izbrani položaj je obrobljen na resnični strani vašega spletnega mesta in sledi položaju, ki ga izberete spodaj. Mobilni predogled spremeni le položaje oglasov; preostali del strani uporablja napravo vašega brskalnika.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'Spletno mesto je trenutno nedosegljivo zaradi težave s podatkovno bazo. Težavo poskušamo čim hitreje odpraviti.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'Spletno mesto je začasno nedosegljivo, ker je disk strežnika poln. Težavo odpravljamo in bomo kmalu spet na voljo.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'Na spletnem mestu poteka vzdrževanje, ker je disk strežnika skoraj poln. Težavo odpravljamo in bomo kmalu spet na voljo.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'Spletno mesto je zavrnilo dostop. Obnovite dostop računa kodirnika in preverite njegova dovoljenja za nalaganje.';
$t['The site will display only a login form to un authenticated users'] = 'The site will display only a login form to un authenticated users';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = 'Izvorni pretok se je končal. Če je bil prenos v živo namerno ustavljen, je to normalno.';
$t['The split is on: desktop visitors do not see this banner now, they see the left and right halves.'] = 'Razdelitev je vklopljena: obiskovalci na namiznih računalnikih zdaj ne vidijo te pasice, temveč levo in desno polovico.';
$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'Pretok ima prekinitve časovnih žigov. To lahko povzroči medpomnjenje ali težave pri predvajanju na ciljni platformi.';
$t['The subtitle has not been copied to the player yet.'] = 'Podnapis še ni bil kopiran v predvajalnik.';
$t['The subtitle is already on the player.'] = 'Podnapis je že v predvajalniku.';
