$t['The upload did not start. Click Resume to try again.'] = 'Nalaganje se ni začelo. Kliknite Nadaljuj za ponovni poskus.';
$t['The upload to YouTube started. You can follow its progress below, it continues even if you close this window.'] = 'Nalaganje na YouTube se je začelo. Napredek lahko spremljate spodaj; nadaljuje se tudi, če zaprete to okno.';
